// Listen to volume changes: Connections { target: Audio.sink?.audio ?? null }
o3->target.bind([=, this]() -> Object* {
  // Audio.sink?.audio ?? null: null without a sink (or for a sink without audio)
  qs::PwNode* node = ::ii::services::Audio::instance().sink.get();
  return node != nullptr ? static_cast<Object*>(node->audio.get()) : nullptr;
}, "OnScreenDisplay/Connections.target");
o3->setConnector([=, this](Object* object, std::vector<Connection>& out) {
  if (object == nullptr) {
    return;
  }
  auto* target = static_cast<qs::PwNodeAudio*>(object);
  // onVolumeChanged: PwNodeAudio has no volumeChanged signal; QML resolves the handler to the NOTIFY
  // signal of `volume`, volumesChanged, which fires whenever any channel volume changes (also when the
  // average stays the same), i.e. when `volumes` changes
  out.push_back(target->volumes.changed().connect([=, this]() {
    if (!::ii::services::Audio::instance().ready.get()) {
      return;
    }
    currentIndicator.set(std::string("volume"));
    this->triggerOsd();
  }));
  out.push_back(target->muted.changed().connect([=, this]() {
    if (!::ii::services::Audio::instance().ready.get()) {
      return;
    }
    currentIndicator.set(std::string("volume"));
    this->triggerOsd();
  }));
});

