// find() gives undefined when no screen matches -> nullptr
const std::optional<qs::ShellScreen*> found = js::find(qs::Quickshell::instance().screens.get(), [](qs::ShellScreen* s) {
  // Hyprland.focusedMonitor?.name is undefined without a focused monitor, and no screen name (a string) === undefined
  qs::HyprlandMonitor* focused = qs::Hyprland::instance().focusedMonitor.get();
  return focused != nullptr && s->name.get() == focused->name.get();
});
return found.value_or(nullptr);

