const std::optional<OsdIndicator> found =
    js::find(this->indicators.get(), [&](const OsdIndicator& i) { return i.id == this->currentIndicator.get(); });
if (!found) {
  // ii: find() gives undefined and ?.sourceUrl stays undefined; a binding that yields undefined for a
  // url property (no RESET) is an error and the Loader keeps its source. Unreachable in practice:
  // currentIndicator only ever holds one of the three ids
  throw std::runtime_error("Unable to assign [undefined] to QUrl");
}
return found->sourceUrl;
